export type ParsedClaimFaucetInstruction<
  TProgram extends string = typeof ANTE_UP_PROGRAM_ADDRESS,
  TAccountMetas extends readonly AccountMeta[] = readonly AccountMeta[],
> = {
  programAddress: Address<TProgram>;
  accounts: {
    financeConfig: TAccountMetas[0];
    paymentMint: TAccountMetas[1];
    recipientPayment: TAccountMetas[2];
    receipt: TAccountMetas[3];
    wallet: TAccountMetas[4];
    tokenProgram: TAccountMetas[5];
    systemProgram: TAccountMetas[6];
  };
  data: ClaimFaucetInstructionData;
};

export function parseClaimFaucetInstruction<
  TProgram extends string,
  TAccountMetas extends readonly AccountMeta[],
>(
  instruction: Instruction<TProgram> &
    InstructionWithAccounts<TAccountMetas> &
    InstructionWithData<ReadonlyUint8Array>,
): ParsedClaimFaucetInstruction<TProgram, TAccountMetas> {
  if (instruction.accounts.length < 7) {
    throw new SolanaError(
      SOLANA_ERROR__PROGRAM_CLIENTS__INSUFFICIENT_ACCOUNT_METAS,
      {
        actualAccountMetas: instruction.accounts.length,
        expectedAccountMetas: 7,
      },
    );
  }
  let accountIndex = 0;
  const getNextAccount = () => {
    const accountMeta = (instruction.accounts as TAccountMetas)[accountIndex]!;
    accountIndex += 1;
    return accountMeta;
  };
  return {
    programAddress: instruction.programAddress,
    accounts: {
      financeConfig: getNextAccount(),
      paymentMint: getNextAccount(),
      recipientPayment: getNextAccount(),
      receipt: getNextAccount(),
      wallet: getNextAccount(),
      tokenProgram: getNextAccount(),
      systemProgram: getNextAccount(),
    },
    data: getClaimFaucetInstructionDataDecoder().decode(instruction.data),
  };
}
